+    };
+    let original = identity(config.clone());
+    assert!(original.has_same_connection_config(&identity(config.clone())));
+    for change in 0..3 {
+        let mut changed = config.clone();
+        match change {
+            0 => {
+                changed["oauth"]["workspace"]["principal_scope"] = serde_json::json!("b".repeat(64))
+            }
+            1 => changed["scopes"] = serde_json::json!([Workspace::SCOPE]),
+            _ => changed["oauth_resource"] = serde_json::json!(Workspace::RESOURCE),
+        }
+        assert!(!original.has_same_connection_config(&identity(changed)));
+    }
+}
