+/// The incumbent Mastermind companion descriptor. These are public connection facts,
+/// never credentials or permission to start a login in the background.
+#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Eq, JsonSchema)]
+#[serde(deny_unknown_fields)]
+pub struct McpWorkspaceOAuthConfig {
+    pub schema: String,
+    pub resource: String,
+    pub identity_url: String,
+    pub scope: String,
+    pub principal_scope: String,
+}
+
+impl McpWorkspaceOAuthConfig {
+    pub const SCHEMA: &str = "mastermind.hermes_workspace_oauth.v1";
+    pub const PRIMARY_SERVER: &str = "mastermind_coo";
+    pub const PRIMARY_URL: &str = "https://mcp.mastermind-x.com/mcp/coo";
+    pub const PRIMARY_RESOURCE: &str = "https://mcp.mastermind-x.com/mcp";
+    pub const PRIMARY_SCOPES: [&str; 2] =
+        ["mastermind.executive.coo.act", "mastermind.executive.read"];
+    pub const SERVER: &str = "mastermind_coo_workspace";
+    pub const RESOURCE: &str = "https://mcp.mastermind-x.com/workspace/read";
+    pub const IDENTITY_URL: &str =
+        "https://mcp.mastermind-x.com/workspace/native-draft-identity/current";
+    pub const SCOPE: &str = "mastermind.workspace.read";
+    pub const HEADER: &str = "x-mastermind-workspace-authorization";
+
+    pub fn validate(&self) -> Result<(), String> {
+        if self.schema != Self::SCHEMA
+            || self.resource != Self::RESOURCE
+            || self.identity_url != Self::IDENTITY_URL
+            || self.scope != Self::SCOPE
+            || self.principal_scope.len() != 64
+            || !self
+                .principal_scope
+                .bytes()
+                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
+        {
+            return Err("WORKSPACE_OAUTH_INVALID_DESCRIPTOR".to_string());
+        }
+        Ok(())
+    }
+
+    pub fn valid_public_client(client_id: &str) -> bool {
+        (2..=256).contains(&client_id.len())
+            && client_id.as_bytes()[0].is_ascii_alphanumeric()
+            && client_id
+                .bytes()
+                .all(|byte| byte.is_ascii_alphanumeric() || b"._:-".contains(&byte))
+    }
+
+    pub fn exact_scopes(scopes: &[String], expected: &[&str]) -> bool {
+        scopes.len() == expected.len()
+            && expected.iter().all(|scope| {
+                scopes
+                    .iter()
+                    .filter(|actual| actual.as_str() == *scope)
+                    .count()
+                    == 1
+            })
+    }
+}
