+#[allow(clippy::too_many_arguments)]
+async fn prepare_workspace_login(
+    name: &str,
+    url: &str,
+    resource: &'static str,
+    scopes: &[&str],
+    config: &McpServerOAuthConfig,
+    store_mode: OAuthCredentialsStoreMode,
+    keyring_backend_kind: AuthKeyringBackendKind,
+    client_registration: McpOAuthClientRegistration,
+    callback_port: Option<u16>,
+    callback_url: Option<&str>,
+    global_callback_url: Option<&str>,
+    http_client: Arc<dyn HttpClient>,
+    launch_browser: bool,
+) -> Result<OauthLoginFlow> {
+    let fixed = Arc::new(crate::workspace_oauth::FixedOAuthHttpClient::new(
+        http_client,
+        resource,
+        config.client_id.as_deref().unwrap_or_default(),
+    ));
+    let scopes = scopes
+        .iter()
+        .map(|scope| (*scope).to_string())
+        .collect::<Vec<_>>();
+    let flow = OauthLoginFlow::new(
+        name,
+        url,
+        store_mode,
+        keyring_backend_kind,
+        OAuthHttpContext {
+            http_headers: None,
+            env_http_headers: None,
+            http_client: fixed.clone(),
+            redirect_mode: StreamableHttpRedirectMode::AgentPluginV1,
+        },
+        &scopes,
+        Some(config),
+        OAuthLoginPurpose::Mcp,
+        client_registration,
+        // RMCP already places the discovered resource in this PKCE authorization.
+        // Appending it again creates an ambiguous duplicate parameter.
+        None,
+        launch_browser,
+        callback_port,
+        callback_url,
+        global_callback_url,
+        None,
+    )
+    .await
+    .map_err(|_| crate::workspace_oauth::WorkspaceOAuthError::ProofUnavailable)?;
+    fixed.require_resource()?;
+    crate::workspace_oauth::validate_authorization_url(
+        &flow.authorization_url(),
+        resource,
+        config.client_id.as_deref().unwrap_or_default(),
+        &scopes,
+    )?;
+    Ok(flow)
+}
