+use super::McpServerConfig;
+use super::McpServerOAuthConfig;
+use super::McpWorkspaceOAuthConfig as Workspace;
+use serde_json::json;
+
+fn selected() -> serde_json::Value {
+    json!({"url":Workspace::PRIMARY_URL,"scopes":Workspace::PRIMARY_SCOPES,
+        "oauth_resource":Workspace::PRIMARY_RESOURCE,"oauth":{"client_id":"selected-client",
+        "workspace":{"schema":Workspace::SCHEMA,"resource":Workspace::RESOURCE,
+            "identity_url":Workspace::IDENTITY_URL,"scope":Workspace::SCOPE,"principal_scope":"a".repeat(64)}}})
+}
+
+#[test]
+fn workspace_pair_config_requires_the_exact_opt_in_connection() {
+    let config: McpServerConfig = serde_json::from_value(selected()).unwrap();
+    assert!(
+        config
+            .validate_workspace_oauth(Workspace::PRIMARY_SERVER)
+            .unwrap()
+            .is_some()
+    );
+    assert!(config.validate_workspace_oauth("alias").is_err());
+    for (key, value) in [
+        ("url", json!("https://other.example/mcp")),
+        ("oauth_resource", json!(Workspace::RESOURCE)),
+        ("scopes", json!([Workspace::SCOPE])),
+        ("environment_id", json!("remote-host")),
+        ("auth", json!("chatgpt")),
+        ("http_headers", json!({"x-header":"override"})),
+        ("bearer_token_env_var", json!("TEST_OVERRIDE")),
+    ] {
+        let mut changed = selected();
+        changed[key] = value;
+        let config: McpServerConfig = serde_json::from_value(changed).unwrap();
+        assert!(
+            config
+                .validate_workspace_oauth(Workspace::PRIMARY_SERVER)
+                .is_err(),
+            "{key}"
+        );
+    }
+}
+
+#[test]
+fn workspace_pair_descriptor_is_closed_and_legacy_encoding_is_unchanged() {
+    let legacy = McpServerOAuthConfig::default();
+    assert_eq!(serde_json::to_value(&legacy).unwrap(), json!({}));
+    let mut changed = selected();
+    changed["oauth"]["workspace"]["access_token"] = json!("never-a-descriptor-field");
+    assert!(serde_json::from_value::<McpServerConfig>(changed).is_err());
+    for value in ["A".repeat(64), "a".repeat(63)] {
+        let mut changed = selected();
+        changed["oauth"]["workspace"]["principal_scope"] = json!(value);
+        let config: McpServerConfig = serde_json::from_value(changed).unwrap();
+        assert!(
+            config
+                .validate_workspace_oauth(Workspace::PRIMARY_SERVER)
+                .is_err()
+        );
+    }
+    let legacy: McpServerConfig =
+        serde_json::from_value(json!({"url":"https://example.com/mcp"})).unwrap();
+    assert!(
+        legacy
+            .validate_workspace_oauth("ordinary")
+            .unwrap()
+            .is_none()
+    );
+}
+
+#[test]
+fn workspace_pair_generated_schema_is_optional_and_closed() {
+    let schema: serde_json::Value =
+        serde_json::from_slice(&crate::schema::config_schema_json().unwrap()).unwrap();
+    assert!(
+        schema
+            .pointer("/definitions/McpServerOAuthConfig/properties/workspace")
+            .is_some()
+    );
+    assert_eq!(
+        schema.pointer("/definitions/McpWorkspaceOAuthConfig/additionalProperties"),
+        Some(&json!(false))
+    );
+    let required = schema
+        .pointer("/definitions/McpWorkspaceOAuthConfig/required")
+        .unwrap()
+        .as_array()
+        .unwrap();
+    assert_eq!(required.len(), 5);
+}
