+//! Fixed Workspace READ authorization on the original Mastermind COO HTTP owner.
+//!
+//! This composes the existing OAuth stores, refresh transaction and HTTP capability.
+//! It never starts a login, creates a network client, retries a request or exports a token.
+
+use std::path::PathBuf;
+use std::sync::Arc;
+use std::sync::OnceLock;
+use std::sync::atomic::AtomicBool;
+use std::sync::atomic::Ordering;
+use std::time::Duration;
+use std::time::SystemTime;
+
+use anyhow::Result;
+use codex_config::McpServerOAuthConfig;
+use codex_config::McpWorkspaceOAuthConfig as Workspace;
+use codex_config::types::AuthKeyringBackendKind;
+use codex_config::types::OAuthCredentialsStoreMode;
+use codex_exec_server::ExecServerError;
+use codex_exec_server::HttpClient;
+use codex_exec_server::HttpHeader;
+use codex_exec_server::HttpRedirectPolicy;
+use codex_exec_server::HttpRequestParams;
+use codex_exec_server::HttpRequestResponse;
+use codex_exec_server::HttpResponseBodyStream;
+use codex_keyring_store::DefaultKeyringStore;
+use codex_otel::auth_storage::AuthStorageOriginator;
+use codex_utils_home_dir::find_codex_home;
+use futures::future::BoxFuture;
+use http::HeaderMap;
+use oauth2::TokenResponse;
+use oauth2::basic::BasicTokenType;
+use serde::Deserialize;
+use tokio::sync::Mutex;
+use url::Url;
+
+use crate::http_client_adapter::StreamableHttpRedirectMode;
+use crate::oauth::OAuthCredentialStore;
+use crate::oauth::OAuthRuntime;
+use crate::oauth::ResolvedOAuthCredentialStore;
+use crate::oauth::ResolvedOAuthTokens;
+use crate::oauth::StoredOAuthTokens;
+use crate::oauth::resolve_oauth_tokens_from_store_policy;
+use crate::oauth_refresh_mode::McpOAuthRefreshMode;
+
+const MAX_IDENTITY_BYTES: usize = 1024;
+const MAX_METADATA_BYTES: usize = 1024 * 1024;
+const PROOF_TIMEOUT: Duration = Duration::from_secs(30);
+
+#[derive(Clone, Copy, Debug, thiserror::Error)]
+pub(crate) enum WorkspaceOAuthError {
+    #[error("WORKSPACE_OAUTH_INVALID_CONNECTION")]
+    InvalidConnection,
+    #[error("WORKSPACE_OAUTH_MISSING_GRANT")]
+    MissingGrant,
+    #[error("WORKSPACE_OAUTH_REFRESH_UNAVAILABLE")]
+    RefreshUnavailable,
+    #[error("WORKSPACE_OAUTH_CONNECTION_CHANGED")]
+    ConnectionChanged,
+    #[error("WORKSPACE_OAUTH_PROOF_UNAVAILABLE")]
+    ProofUnavailable,
+    #[error("WORKSPACE_OAUTH_REQUIRES_FIXED_BROWSER_LOGIN")]
+    BrowserLoginRequired,
+    #[error("WORKSPACE_OAUTH_GRANT_REJECTED")]
+    GrantRejected,
+    #[error("WORKSPACE_OAUTH_LOGIN_INCOMPLETE")]
+    LoginIncomplete,
+    #[error("WORKSPACE_OAUTH_ORIGINAL_OUTCOME_UNCERTAIN")]
+    OriginalOutcomeUncertain,
+}
+
+impl WorkspaceOAuthError {
+    fn http(self) -> ExecServerError {
+        // This is a fixed authorization/currentness contract outcome, not the
+        // generic transient HTTP error that the incumbent initialize/list owner
+        // retries. Preserve the closed code without creating another retry owner.
+        ExecServerError::Protocol(self.to_string())
+    }
+}
+
+pub(crate) fn descriptor(config: Option<&McpServerOAuthConfig>) -> Option<&Workspace> {
+    config.and_then(|config| config.workspace.as_ref())
+}
+
+pub(crate) fn validate_connection<'a>(
+    name: &str,
+    url: &str,
+    config: &'a McpServerOAuthConfig,
+) -> Result<&'a Workspace> {
+    let selected = config
+        .workspace
+        .as_ref()
+        .ok_or(WorkspaceOAuthError::InvalidConnection)?;
+    selected
+        .validate()
+        .map_err(|_| WorkspaceOAuthError::InvalidConnection)?;
+    if name != Workspace::PRIMARY_SERVER
+        || url != Workspace::PRIMARY_URL
+        || !config
+            .client_id
+            .as_deref()
+            .is_some_and(Workspace::valid_public_client)
+        || config.client_secret.is_some()
+        || config.token_endpoint_auth_method.is_some()
+        || config.authorization_server_issuer.is_some()
+        || config.ema_registration.is_some()
+    {
+        return Err(WorkspaceOAuthError::InvalidConnection.into());
+    }
+    Ok(selected)
+}
+
+fn now_ms() -> Result<u64> {
+    u64::try_from(
+        SystemTime::now()
+            .duration_since(SystemTime::UNIX_EPOCH)?
+            .as_millis(),
+    )
+    .map_err(Into::into)
+}
+
+pub(crate) fn validate_tokens(
+    tokens: &StoredOAuthTokens,
+    name: &str,
+    url: &str,
+    config: &McpServerOAuthConfig,
+    require_live: bool,
+) -> Result<()> {
+    let scopes: &[&str] = match (name, url) {
+        (Workspace::PRIMARY_SERVER, Workspace::PRIMARY_URL) => &Workspace::PRIMARY_SCOPES,
+        (Workspace::SERVER, Workspace::RESOURCE) => &[Workspace::SCOPE],
+        _ => return Err(WorkspaceOAuthError::InvalidConnection.into()),
+    };
+    let granted = tokens.token_response.0.scopes().map(|scopes| {
+        scopes
+            .iter()
+            .map(|scope| scope.as_str().to_string())
+            .collect::<Vec<_>>()
+    });
+    if tokens.server_name != name
+        || tokens.url != url
+        || Some(tokens.client_id.as_str()) != config.client_id.as_deref()
+        || tokens.bound_issuer().is_none()
+        || tokens.token_response.0.token_type() != &BasicTokenType::Bearer
+        || !granted
+            .as_ref()
+            .is_some_and(|granted| Workspace::exact_scopes(granted, scopes))
+        || tokens.expires_at.is_none()
+        || !valid_bearer(tokens.token_response.0.access_token().secret())
+    {
+        return Err(WorkspaceOAuthError::ConnectionChanged.into());
+    }
+    if require_live
+        && tokens
+            .expires_at
+            .is_none_or(|expiry| now_ms().map_or(true, |now| now >= expiry))
+    {
+        return Err(WorkspaceOAuthError::RefreshUnavailable.into());
+    }
+    Ok(())
+}
+
+fn valid_bearer(token: &str) -> bool {
+    let value = token.trim_end_matches('=');
+    !value.is_empty()
+        && value
+            .bytes()
+            .all(|byte| byte.is_ascii_alphanumeric() || b"._~+/-".contains(&byte))
+        && token[value.len()..].bytes().all(|byte| byte == b'=')
+}
+
+pub(crate) fn validate_authorization_url(
+    value: &str,
+    resource: &str,
+    client_id: &str,
+    scopes: &[String],
+) -> Result<()> {
+    let url = Url::parse(value).map_err(|_| WorkspaceOAuthError::InvalidConnection)?;
+    let values = |key: &str| {
+        url.query_pairs()
+            .filter(|(name, _)| name == key)
+            .map(|(_, value)| value.into_owned())
+            .collect::<Vec<_>>()
+    };
+    let scope = values("scope");
+    let actual_scopes = scope
+        .first()
+        .map(|value| {
+            value
+                .split_whitespace()
+                .map(str::to_string)
+                .collect::<Vec<_>>()
+        })
+        .unwrap_or_default();
+    let expected_scopes = scopes.iter().map(String::as_str).collect::<Vec<_>>();
+    if url.scheme() != "https"
+        || !url.username().is_empty()
+        || url.password().is_some()
+        || url.fragment().is_some()
+        || values("resource") != [resource]
+        || values("client_id") != [client_id]
+        || scope.len() != 1
+        || !Workspace::exact_scopes(&actual_scopes, &expected_scopes)
+        || values("response_type") != ["code"]
+        || values("code_challenge_method") != ["S256"]
+        || values("code_challenge").len() != 1
+        || values("state").len() != 1
+    {
+        return Err(WorkspaceOAuthError::InvalidConnection.into());
+    }
+    Ok(())
+}
+
+fn header<'a>(headers: &'a [HttpHeader], name: &str) -> Result<Option<&'a str>> {
+    let mut found = headers
+        .iter()
+        .filter(|header| header.name.eq_ignore_ascii_case(name));
+    let value = found.next();
+    if found.next().is_some() || value.is_some_and(|header| header.value_env_var.is_some()) {
+        return Err(WorkspaceOAuthError::InvalidConnection.into());
+    }
+    Ok(value.map(|header| header.value.as_str()))
+}
+
+/// The same original HTTP capability with fixed OAuth request/response checks.
+/// The flag records this manager's real protected-resource metadata acquisition.
+pub(crate) struct FixedOAuthHttpClient {
+    inner: Arc<dyn HttpClient>,
+    resource: &'static str,
+    client_id: String,
+    resource_observed: AtomicBool,
+}
+
+impl FixedOAuthHttpClient {
+    pub(crate) fn new(inner: Arc<dyn HttpClient>, resource: &'static str, client_id: &str) -> Self {
+        Self {
+            inner,
+            resource,
+            client_id: client_id.to_string(),
+            resource_observed: AtomicBool::new(false),
+        }
+    }
+
+    pub(crate) fn require_resource(&self) -> Result<()> {
+        if !self.resource_observed.load(Ordering::Acquire) {
+            return Err(WorkspaceOAuthError::ProofUnavailable.into());
+        }
+        Ok(())
+    }
+
+    fn check_request(&self, params: &mut HttpRequestParams) -> Result<()> {
+        let url = Url::parse(&params.url).map_err(|_| WorkspaceOAuthError::InvalidConnection)?;
+        if url.scheme() != "https"
+            || url.host_str().is_none()
+            || !url.username().is_empty()
+            || url.password().is_some()
+            || url.fragment().is_some()
+            || header(&params.headers, Workspace::HEADER)?.is_some()
+            || header(&params.headers, "authorization")?.is_some()
+        {
+            return Err(WorkspaceOAuthError::InvalidConnection.into());
+        }
+        params.redirect_policy = HttpRedirectPolicy::Stop;
+        if params.method == "POST" {
+            self.require_resource()?;
+            if url.query().is_some() {
+                return Err(WorkspaceOAuthError::InvalidConnection.into());
+            }
+            let body = params
+                .body
+                .as_ref()
+                .ok_or(WorkspaceOAuthError::InvalidConnection)?;
+            let pairs = url::form_urlencoded::parse(body.as_ref())
+                .into_owned()
+                .collect::<Vec<_>>();
+            let exact = |name: &str, value: &str| {
+                let values = pairs
+                    .iter()
+                    .filter(|(key, _)| key == name)
+                    .map(|(_, value)| value.as_str())
+                    .collect::<Vec<_>>();
+                values == [value]
+            };
+            if (!exact("grant_type", "authorization_code") && !exact("grant_type", "refresh_token"))
+                || !exact("resource", self.resource)
+                || !exact("client_id", &self.client_id)
+            {
+                return Err(WorkspaceOAuthError::InvalidConnection.into());
+            }
+        } else if params.method != "GET" {
+            return Err(WorkspaceOAuthError::InvalidConnection.into());
+        }
+        Ok(())
+    }
+
+    fn check_response(
+        &self,
+        params: &HttpRequestParams,
+        response: &HttpRequestResponse,
+        body: &[u8],
+    ) -> Result<()> {
+        // Let the existing OAuth manager classify real token rejection and discovery
+        // missingness. Never turn an invalid_grant into a retryable network error.
+        if (300..400).contains(&response.status) {
+            return Err(WorkspaceOAuthError::ProofUnavailable.into());
+        }
+        let url = Url::parse(&params.url).map_err(|_| WorkspaceOAuthError::InvalidConnection)?;
+        if params.method == "GET"
+            && (200..300).contains(&response.status)
+            && url
+                .path()
+                .starts_with("/.well-known/oauth-protected-resource")
+        {
+            #[derive(Deserialize)]
+            struct Resource {
+                resource: String,
+            }
+            let value: Resource =
+                serde_json::from_slice(body).map_err(|_| WorkspaceOAuthError::ProofUnavailable)?;
+            if value.resource != self.resource
+                || url.origin() != Url::parse(self.resource)?.origin()
+            {
+                return Err(WorkspaceOAuthError::InvalidConnection.into());
+            }
+            self.resource_observed.store(true, Ordering::Release);
+        }
+        if params.method == "POST" && (200..300).contains(&response.status) {
+            let value: serde_json::Value =
+                serde_json::from_slice(body).map_err(|_| WorkspaceOAuthError::ProofUnavailable)?;
+            let expected = if self.resource == Workspace::PRIMARY_RESOURCE {
+                Workspace::PRIMARY_SCOPES.as_slice()
+            } else {
+                &[Workspace::SCOPE][..]
+            };
+            let scope = value.get("scope").and_then(serde_json::Value::as_str);
+            let refresh = params.body.as_ref().is_some_and(|body| {
+                url::form_urlencoded::parse(body.as_ref())
+                    .any(|(key, value)| key == "grant_type" && value == "refresh_token")
+            });
+            // Only a refresh can retain the original store's already-proven scope.
+            // Initial authorization must provide an explicit exact grant.
+            if scope.is_none() && !refresh
+                || scope.is_some_and(|scope| {
+                    !Workspace::exact_scopes(
+                        &scope
+                            .split_whitespace()
+                            .map(str::to_string)
+                            .collect::<Vec<_>>(),
+                        expected,
+                    )
+                })
+            {
+                return Err(WorkspaceOAuthError::GrantRejected.into());
+            }
+        }
+        Ok(())
+    }
+
+    async fn request(
+        &self,
+        mut params: HttpRequestParams,
+    ) -> Result<(HttpRequestResponse, Vec<u8>), ExecServerError> {
+        self.check_request(&mut params)
+            .map_err(|_| WorkspaceOAuthError::InvalidConnection.http())?;
+        let (mut response, mut stream) = self
+            .inner
+            .http_request_stream(params.clone())
+            .await
+            .map_err(|_| WorkspaceOAuthError::ProofUnavailable.http())?;
+        let mut body = response.body.as_ref().to_vec();
+        if body.len() > MAX_METADATA_BYTES {
+            return Err(WorkspaceOAuthError::ProofUnavailable.http());
+        }
+        while let Some(chunk) = stream
+            .recv()
+            .await
+            .map_err(|_| WorkspaceOAuthError::ProofUnavailable.http())?
+        {
+            if body.len().saturating_add(chunk.len()) > MAX_METADATA_BYTES {
+                return Err(WorkspaceOAuthError::ProofUnavailable.http());
+            }
+            body.extend(chunk);
+        }
+        self.check_response(&params, &response, &body)
+            .map_err(|_| WorkspaceOAuthError::ProofUnavailable.http())?;
+        if params.method == "POST" && !(200..300).contains(&response.status) {
+            // Preserve the original manager's definitive rejection classification,
+            // without reflecting arbitrary provider descriptions or token data.
+            let value = serde_json::from_slice::<serde_json::Value>(&body).ok();
+            let code = value
+                .as_ref()
+                .and_then(|value| value.get("error"))
+                .and_then(serde_json::Value::as_str)
+                .filter(|code| {
+                    matches!(
+                        *code,
+                        "invalid_grant"
+                            | "invalid_client"
+                            | "invalid_request"
+                            | "unauthorized_client"
+                            | "unsupported_grant_type"
+                            | "invalid_scope"
+                            | "server_error"
+                            | "temporarily_unavailable"
+                    )
+                })
+                .unwrap_or("server_error");
+            body = serde_json::to_vec(&serde_json::json!({"error":code}))
+                .map_err(|_| WorkspaceOAuthError::ProofUnavailable.http())?;
+            response.headers.retain(|header| {
+                !header.name.eq_ignore_ascii_case("content-length")
+                    && !header.name.eq_ignore_ascii_case("content-encoding")
+            });
+        }
+        response.body = Vec::new().into();
+        Ok((response, body))
+    }
+}
+
+impl HttpClient for FixedOAuthHttpClient {
+    fn http_request(
+        &self,
+        params: HttpRequestParams,
+    ) -> BoxFuture<'_, Result<HttpRequestResponse, ExecServerError>> {
+        Box::pin(async move {
+            let (mut response, body) = self.request(params).await?;
+            response.body = body.into();
+            Ok(response)
+        })
+    }
+    fn http_request_stream(
+        &self,
+        params: HttpRequestParams,
+    ) -> BoxFuture<'_, Result<(HttpRequestResponse, HttpResponseBodyStream), ExecServerError>> {
+        Box::pin(async move {
+            let (response, body) = self.request(params).await?;
+            Ok((response, HttpResponseBodyStream::from_chunks(vec![body])))
+        })
+    }
+}
+
+pub(crate) struct WorkspaceHttpClient {
+    inner: Arc<dyn HttpClient>,
+    descriptor: Workspace,
+    config: McpServerOAuthConfig,
+    home: PathBuf,
+    primary: OAuthCredentialStore,
+    companion: OAuthCredentialStore,
+    runtime: OAuthRuntime,
+}
+
+pub(crate) fn current_home() -> Result<PathBuf> {
+    Ok(find_codex_home()
+        .map_err(|_| WorkspaceOAuthError::MissingGrant)?
+        .canonicalize()
+        .map_err(|_| WorkspaceOAuthError::MissingGrant)?
+        .to_path_buf())
+}
+
+pub(crate) fn pin_home(pinned: &OnceLock<PathBuf>) -> Result<PathBuf> {
+    let home = current_home()?;
+    let original = pinned.get_or_init(|| home.clone());
+    if original != &home {
+        return Err(WorkspaceOAuthError::ConnectionChanged.into());
+    }
+    Ok(home)
+}
+
+#[allow(clippy::too_many_arguments)]
+pub(crate) async fn bind_primary(
+    inner: Arc<dyn HttpClient>,
+    config: &McpServerOAuthConfig,
+    primary: OAuthCredentialStore,
+    store_mode: OAuthCredentialsStoreMode,
+    keyring_backend_kind: AuthKeyringBackendKind,
+    pinned_store: Arc<OnceLock<ResolvedOAuthCredentialStore>>,
+    pinned_home: Arc<OnceLock<PathBuf>>,
+    originator: AuthStorageOriginator,
+) -> Result<Arc<dyn HttpClient>> {
+    let descriptor = config
+        .workspace
+        .as_ref()
+        .ok_or(WorkspaceOAuthError::InvalidConnection)?
+        .clone();
+    let home = pin_home(&pinned_home)?;
+    let was_bound = pinned_store.get().is_some();
+    let load = move || -> Result<ResolvedOAuthTokens> {
+        if let Some(store) = pinned_store.get().copied() {
+            let tokens = store
+                .load(&DefaultKeyringStore, Workspace::SERVER, Workspace::RESOURCE)?
+                .ok_or(WorkspaceOAuthError::MissingGrant)?;
+            return Ok(ResolvedOAuthTokens { tokens, store });
+        }
+        let resolved = resolve_oauth_tokens_from_store_policy(
+            &DefaultKeyringStore,
+            Workspace::SERVER,
+            Workspace::RESOURCE,
+            store_mode,
+            keyring_backend_kind,
+        )?
+        .ok_or(WorkspaceOAuthError::MissingGrant)?;
+        pinned_store
+            .set(resolved.store)
+            .map_err(|_| WorkspaceOAuthError::ConnectionChanged)?;
+        Ok(resolved)
+    };
+    let resolved = tokio::task::spawn_blocking(move || originator.sync_scope(load))
+        .await
+        .map_err(|_| WorkspaceOAuthError::MissingGrant)?
+        .map_err(|_| {
+            if was_bound {
+                WorkspaceOAuthError::ConnectionChanged
+            } else {
+                WorkspaceOAuthError::MissingGrant
+            }
+        })?;
+    pin_home(&pinned_home)?;
+    validate_tokens(
+        &resolved.tokens,
+        Workspace::SERVER,
+        Workspace::RESOURCE,
+        config,
+        false,
+    )?;
+    let fixed = Arc::new(FixedOAuthHttpClient::new(
+        Arc::clone(&inner),
+        Workspace::RESOURCE,
+        config
+            .client_id
+            .as_deref()
+            .ok_or(WorkspaceOAuthError::InvalidConnection)?,
+    ));
+    let prepared = crate::rmcp_client::prepare_oauth_manager(
+        Workspace::RESOURCE,
+        resolved.tokens,
+        resolved.store,
+        HeaderMap::new(),
+        fixed.clone(),
+        false,
+        StreamableHttpRedirectMode::AgentPluginV1,
+        McpOAuthRefreshMode::Coordinated,
+        Some(config),
+    )
+    .await
+    .map_err(|_| WorkspaceOAuthError::ProofUnavailable)?;
+    fixed.require_resource()?;
+    let companion = prepared.store.ok_or(WorkspaceOAuthError::MissingGrant)?;
+    let runtime = OAuthRuntime::Coordinated {
+        auth_manager: Arc::new(Mutex::new(prepared.manager)),
+        store: companion.clone(),
+    };
+    Ok(Arc::new(WorkspaceHttpClient {
+        inner,
+        descriptor,
+        config: config.clone(),
+        home,
+        primary,
+        companion,
+        runtime,
+    }))
+}
+
+struct RequestProof {
+    primary: StoredOAuthTokens,
+    companion: StoredOAuthTokens,
+    expires_at_ms: u64,
+}
+
+impl WorkspaceHttpClient {
+    fn require_home(&self) -> Result<()> {
+        if find_codex_home()
+            .ok()
+            .and_then(|home| home.canonicalize().ok())
+            .map(|home| home.to_path_buf())
+            .as_ref()
+            != Some(&self.home)
+        {
+            return Err(WorkspaceOAuthError::ConnectionChanged.into());
+        }
+        Ok(())
+    }
+
+    async fn current(
+        &self,
+        store: &OAuthCredentialStore,
+        name: &str,
+        url: &str,
+        live: bool,
+    ) -> Result<StoredOAuthTokens> {
+        self.require_home()?;
+        let guard = store
+            .acquire_transaction_guard()
+            .await
+            .map_err(|error| match error {
+                rmcp::transport::auth::AuthError::TokenExpired => {
+                    WorkspaceOAuthError::RefreshUnavailable
+                }
+                _ => WorkspaceOAuthError::ConnectionChanged,
+            })?;
+        let tokens = store
+            .stored_credentials()
+            .await
+            .ok_or(WorkspaceOAuthError::ConnectionChanged)?;
+        drop(guard);
+        self.require_home()?;
+        validate_tokens(&tokens, name, url, &self.config, live)?;
+        Ok(tokens)
+    }
+
+    async fn prepare(&self, request: &mut HttpRequestParams) -> Result<RequestProof> {
+        self.require_home()?;
+        if request.url != Workspace::PRIMARY_URL
+            || !matches!(request.method.as_str(), "GET" | "POST" | "DELETE")
+            || header(&request.headers, Workspace::HEADER)?.is_some()
+        {
+            return Err(WorkspaceOAuthError::InvalidConnection.into());
+        }
+        let primary = self
+            .current(
+                &self.primary,
+                Workspace::PRIMARY_SERVER,
+                Workspace::PRIMARY_URL,
+                true,
+            )
+            .await?;
+        let auth = format!(
+            "Bearer {}",
+            primary.token_response.0.access_token().secret()
+        );
+        if header(&request.headers, "authorization")? != Some(auth.as_str()) {
+            return Err(WorkspaceOAuthError::ConnectionChanged.into());
+        }
+        self.current(
+            &self.companion,
+            Workspace::SERVER,
+            Workspace::RESOURCE,
+            false,
+        )
+        .await?;
+        self.runtime
+            .refresh_if_needed()
+            .await
+            .map_err(|_| WorkspaceOAuthError::RefreshUnavailable)?;
+        let companion = self
+            .current(
+                &self.companion,
+                Workspace::SERVER,
+                Workspace::RESOURCE,
+                true,
+            )
+            .await?;
+        let bearer = format!(
+            "Bearer {}",
+            companion.token_response.0.access_token().secret()
+        );
+        let timeout = request
+            .timeout_ms
+            .map(Duration::from_millis)
+            .unwrap_or(PROOF_TIMEOUT)
+            .min(PROOF_TIMEOUT);
+        let proof_request = HttpRequestParams {
+            method: "GET".to_string(),
+            url: Workspace::IDENTITY_URL.to_string(),
+            headers: vec![
+                HttpHeader {
+                    name: "authorization".to_string(),
+                    value: bearer.clone(),
+                    value_env_var: None,
+                },
+                HttpHeader {
+                    name: "accept".to_string(),
+                    value: "application/json".to_string(),
+                    value_env_var: None,
+                },
+            ],
+            body: None,
+            timeout_ms: Some(u64::try_from(timeout.as_millis()).unwrap_or(u64::MAX)),
+            redirect_policy: HttpRedirectPolicy::Stop,
+            request_id: format!("{}:workspace-identity", request.request_id),
+            stream_response: true,
+        };
+        let identity = tokio::time::timeout(timeout, async {
+            let (response, mut stream) = self
+                .inner
+                .http_request_stream(proof_request)
+                .await
+                .map_err(|_| WorkspaceOAuthError::ProofUnavailable)?;
+            if response.status != 200
+                || header(&response.headers, "content-type")?.is_none_or(|value| {
+                    value.split(';').next().map(str::trim) != Some("application/json")
+                })
+            {
+                return Err(WorkspaceOAuthError::ProofUnavailable.into());
+            }
+            let mut body = response.body.as_ref().to_vec();
+            if body.len() > MAX_IDENTITY_BYTES {
+                return Err(WorkspaceOAuthError::ProofUnavailable.into());
+            }
+            while let Some(chunk) = stream
+                .recv()
+                .await
+                .map_err(|_| WorkspaceOAuthError::ProofUnavailable)?
+            {
+                if body.len().saturating_add(chunk.len()) > MAX_IDENTITY_BYTES {
+                    return Err(WorkspaceOAuthError::ProofUnavailable.into());
+                }
+                body.extend(chunk);
+            }
+            #[derive(Deserialize)]
+            #[serde(deny_unknown_fields)]
+            struct Identity {
+                schema: String,
+                principal_scope: String,
+                expires_at_ms: u64,
+            }
+            let identity: Identity =
+                serde_json::from_slice(&body).map_err(|_| WorkspaceOAuthError::ProofUnavailable)?;
+            if identity.schema != "mastermind.native_draft_identity.v1"
+                || identity.principal_scope != self.descriptor.principal_scope
+                || identity.expires_at_ms <= now_ms()?
+            {
+                return Err(WorkspaceOAuthError::ProofUnavailable.into());
+            }
+            Ok::<_, anyhow::Error>(identity.expires_at_ms)
+        })
+        .await
+        .map_err(|_| WorkspaceOAuthError::ProofUnavailable)??;
+        let proof = RequestProof {
+            primary,
+            companion,
+            expires_at_ms: identity,
+        };
+        self.check(&proof).await?;
+        request.redirect_policy = HttpRedirectPolicy::Stop;
+        request.headers.push(HttpHeader {
+            name: Workspace::HEADER.to_string(),
+            value: bearer,
+            value_env_var: None,
+        });
+        Ok(proof)
+    }
+
+    async fn check(&self, proof: &RequestProof) -> Result<()> {
+        if now_ms()? >= proof.expires_at_ms
+            || self
+                .current(
+                    &self.primary,
+                    Workspace::PRIMARY_SERVER,
+                    Workspace::PRIMARY_URL,
+                    true,
+                )
+                .await?
+                != proof.primary
+            || self
+                .current(
+                    &self.companion,
+                    Workspace::SERVER,
+                    Workspace::RESOURCE,
+                    true,
+                )
+                .await?
+                != proof.companion
+        {
+            return Err(WorkspaceOAuthError::ConnectionChanged.into());
+        }
+        Ok(())
+    }
+}
+
+impl HttpClient for WorkspaceHttpClient {
+    fn http_request(
+        &self,
+        mut params: HttpRequestParams,
+    ) -> BoxFuture<'_, Result<HttpRequestResponse, ExecServerError>> {
+        Box::pin(async move {
+            let proof = self
+                .prepare(&mut params)
+                .await
+                .map_err(|error| safe_http_error(&error))?;
+            let response = self
+                .inner
+                .http_request(params)
+                .await
+                .map_err(after_send_error)?;
+            self.check(&proof)
+                .await
+                .map_err(|_| WorkspaceOAuthError::OriginalOutcomeUncertain.http())?;
+            check_original_response(response.status)?;
+            Ok(response)
+        })
+    }
+    fn http_request_stream(
+        &self,
+        mut params: HttpRequestParams,
+    ) -> BoxFuture<'_, Result<(HttpRequestResponse, HttpResponseBodyStream), ExecServerError>> {
+        Box::pin(async move {
+            let proof = self
+                .prepare(&mut params)
+                .await
+                .map_err(|error| safe_http_error(&error))?;
+            let response = self
+                .inner
+                .http_request_stream(params)
+                .await
+                .map_err(after_send_error)?;
+            self.check(&proof)
+                .await
+                .map_err(|_| WorkspaceOAuthError::OriginalOutcomeUncertain.http())?;
+            check_original_response(response.0.status)?;
+            Ok(response)
+        })
+    }
+}
+
+fn after_send_error(error: ExecServerError) -> ExecServerError {
+    match error {
+        // Preserve only the transport owner's explicit prewrite proof, without its data.
+        ExecServerError::RequestNotSent(_) => {
+            ExecServerError::RequestNotSent("WORKSPACE_OAUTH_ORIGINAL_NOT_SENT".to_string())
+        }
+        _ => WorkspaceOAuthError::OriginalOutcomeUncertain.http(),
+    }
+}
+
+fn check_original_response(status: u16) -> Result<(), ExecServerError> {
+    // AuthClient otherwise refreshes and repeats a rejected MCP request. This fixed
+    // pair refreshes only before the original request; no companion/primary replay.
+    if matches!(status, 401 | 403) {
+        return Err(WorkspaceOAuthError::GrantRejected.http());
+    }
+    if (300..400).contains(&status) {
+        return Err(WorkspaceOAuthError::OriginalOutcomeUncertain.http());
+    }
+    Ok(())
+}
+
+fn safe_http_error(error: &anyhow::Error) -> ExecServerError {
+    error
+        .downcast_ref::<WorkspaceOAuthError>()
+        .copied()
+        .unwrap_or(WorkspaceOAuthError::ProofUnavailable)
+        .http()
+}
