+const ISSUER: &str = "https://login.mastermind-x.com";
+const CLIENT: &str = "test-native-client";
+
+pub(crate) fn config() -> McpServerOAuthConfig {
+    McpServerOAuthConfig {
+        client_id: Some(CLIENT.to_string()),
+        workspace: Some(Workspace {
+            schema: Workspace::SCHEMA.into(),
+            resource: Workspace::RESOURCE.into(),
+            identity_url: Workspace::IDENTITY_URL.into(),
+            scope: Workspace::SCOPE.into(),
+            principal_scope: "a".repeat(64),
+        }),
+        ..Default::default()
+    }
+}
+
+fn tokens(companion: bool, expires_at: u64) -> StoredOAuthTokens {
+    StoredOAuthTokens {
+        server_name: if companion { Workspace::SERVER } else { Workspace::PRIMARY_SERVER }.into(),
+        url: if companion { Workspace::RESOURCE } else { Workspace::PRIMARY_URL }.into(),
+        issuer: Some(ISSUER.into()), client_id: CLIENT.into(), expires_at: Some(expires_at),
+        token_response: WrappedOAuthTokenResponse(serde_json::from_value(json!({
+            "access_token": if companion { "workspace-token" } else { "executive-token" },
+            "refresh_token": if companion { "workspace-refresh" } else { "executive-refresh" },
+            "token_type":"Bearer", "expires_in":600,
+            "scope": if companion { Workspace::SCOPE.to_string() } else { Workspace::PRIMARY_SCOPES.join(" ") }
+        })).unwrap()),
+    }
+}
