+#[derive(Default)]
+pub(crate) struct FixtureHttp {
+    pub(crate) calls: StdMutex<Vec<(String, String)>>,
+    proof_count: AtomicUsize,
+    original_count: AtomicUsize,
+    refresh_count: AtomicUsize,
+    pub(crate) mode: AtomicUsize,
+    entered: tokio::sync::Notify,
+    cancelled: AtomicBool,
+}
+
+impl FixtureHttp {
+    fn response(status: u16, value: serde_json::Value) -> HttpRequestResponse {
+        HttpRequestResponse {
+            status,
+            headers: vec![HttpHeader {
+                name: "content-type".into(),
+                value: "application/json".into(),
+                value_env_var: None,
+            }],
+            body: serde_json::to_vec(&value).unwrap().into(),
+        }
+    }
+
+    async fn execute(
+        &self,
+        params: HttpRequestParams,
+    ) -> Result<HttpRequestResponse, ExecServerError> {
+        self.calls
+            .lock()
+            .unwrap()
+            .push((params.method.clone(), params.url.clone()));
+        let mode = self.mode.load(Ordering::SeqCst);
+        if params.url == Workspace::IDENTITY_URL {
+            assert_eq!(params.redirect_policy, HttpRedirectPolicy::Stop);
+            assert!(
+                header(&params.headers, Workspace::HEADER)
+                    .unwrap()
+                    .is_none()
+            );
+            assert!(
+                header(&params.headers, "authorization")
+                    .unwrap()
+                    .is_some_and(|value| value.starts_with("Bearer workspace-"))
+            );
+            self.proof_count.fetch_add(1, Ordering::SeqCst);
+            if mode == 10 {
+                struct Cancelled<'a>(&'a AtomicBool);
+                impl Drop for Cancelled<'_> {
+                    fn drop(&mut self) {
+                        self.0.store(true, Ordering::SeqCst);
+                    }
+                }
+                let _drop = Cancelled(&self.cancelled);
+                self.entered.notify_one();
+                futures::future::pending::<()>().await;
+            }
+            if mode == 1 {
+                return Ok(Self::response(403, json!({"error":"denied"})));
+            }
+            if mode == 2 {
+                return Ok(Self::response(
+                    200,
+                    json!({"schema":"mastermind.native_draft_identity.v1","principal_scope":"b".repeat(64),"expires_at_ms":now_ms().unwrap()+60000}),
+                ));
+            }
+            if mode == 3 {
+                return Ok(Self::response(200, json!({"padding":"x".repeat(1025)})));
+            }
+            if mode == 12 {
+                return Ok(Self::response(
+                    200,
+                    json!({"schema":"mastermind.native_draft_identity.v1","principal_scope":"a".repeat(64),"expires_at_ms":1}),
+                ));
+            }
+            if mode == 13 {
+                return Ok(Self::response(
+                    200,
+                    json!({"schema":"mastermind.native_draft_identity.v1","principal_scope":"a".repeat(64),"expires_at_ms":now_ms().unwrap()+60000,"extra":true}),
+                ));
+            }
+            if mode == 14 {
+                return Ok(Self::response(302, json!({})));
+            }
+            if mode == 4 {
+                let mut replacement = tokens(true, now_ms().unwrap() + 600000);
+                replacement.client_id = "foreign-client".into();
+                save(&replacement).await;
+            }
+            return Ok(Self::response(
+                200,
+                json!({"schema":"mastermind.native_draft_identity.v1","principal_scope":"a".repeat(64),"expires_at_ms":now_ms().unwrap()+60000}),
+            ));
+        }
+        if params.url.contains("/.well-known/oauth-protected-resource") {
+            assert!(
+                header(&params.headers, Workspace::HEADER)
+                    .unwrap()
+                    .is_none()
+            );
+            assert!(header(&params.headers, "authorization").unwrap().is_none());
+            let resource = if params.url.contains("workspace") {
+                Workspace::RESOURCE
+            } else {
+                Workspace::PRIMARY_RESOURCE
+            };
+            return Ok(Self::response(
+                200,
+                json!({"resource":resource,"authorization_servers":[ISSUER]}),
+            ));
+        }
+        if params
+            .url
+            .contains("/.well-known/oauth-authorization-server")
+            || params.url.contains("/.well-known/openid-configuration")
+        {
+            return Ok(Self::response(
+                200,
+                json!({"issuer":ISSUER,
+                "authorization_endpoint":format!("{ISSUER}/authorize"),"token_endpoint":format!("{ISSUER}/token"),
+                "response_types_supported":["code"],"grant_types_supported":["authorization_code","refresh_token"],
+                "code_challenge_methods_supported":["S256"],"token_endpoint_auth_methods_supported":["none"],
+                "authorization_response_iss_parameter_supported":true}),
+            ));
+        }
+        if params.url == format!("{ISSUER}/token") {
+            assert_eq!(params.redirect_policy, HttpRedirectPolicy::Stop);
+            assert!(
+                header(&params.headers, Workspace::HEADER)
+                    .unwrap()
+                    .is_none()
+            );
+            assert!(header(&params.headers, "authorization").unwrap().is_none());
+            let body = params.body.as_ref().unwrap();
+            let form = url::form_urlencoded::parse(body.as_ref())
+                .collect::<std::collections::HashMap<_, _>>();
+            assert_eq!(form.get("client_id").map(|v| v.as_ref()), Some(CLIENT));
+            let companion = form
+                .get("resource")
+                .is_some_and(|v| v == Workspace::RESOURCE);
+            if form
+                .get("grant_type")
+                .is_some_and(|v| v == "authorization_code")
+            {
+                assert!(
+                    form.get("code_verifier")
+                        .is_some_and(|value| value.len() >= 43)
+                );
+            }
+            if form.get("grant_type").is_some_and(|v| v == "refresh_token") {
+                self.refresh_count.fetch_add(1, Ordering::SeqCst);
+            }
+            if mode == 11 {
+                return Ok(Self::response(
+                    400,
+                    json!({"error":"invalid_grant", "error_description":"provider-description-must-not-escape"}),
+                ));
+            }
+            return Ok(Self::response(
+                200,
+                json!({"access_token":if companion {"workspace-refreshed"}else{"executive-refreshed"},
+                "refresh_token":"replacement-refresh","token_type":"Bearer","expires_in":600,
+                "scope": if companion {Workspace::SCOPE.to_string()}else{Workspace::PRIMARY_SCOPES.join(" ")}}),
+            ));
+        }
+        if params.url == Workspace::PRIMARY_URL
+            && header(&params.headers, "authorization").unwrap().is_some()
+        {
+            assert_eq!(params.redirect_policy, HttpRedirectPolicy::Stop);
+            assert!(
+                header(&params.headers, Workspace::HEADER)
+                    .unwrap()
+                    .is_some_and(|v| v.starts_with("Bearer workspace-"))
+            );
+            self.original_count.fetch_add(1, Ordering::SeqCst);
+            if mode == 5 {
+                return Err(ExecServerError::HttpRequest(
+                    "lost original response (fixture)".into(),
+                ));
+            }
+            if mode == 6 {
+                let mut replacement = tokens(true, now_ms().unwrap() + 600000);
+                replacement.client_id = "replaced-after-send".into();
+                save(&replacement).await;
+            }
+            if mode == 7 {
+                return Ok(Self::response(401, json!({"error":"invalid_token"})));
+            }
+            if params.method == "POST" {
+                let value: serde_json::Value =
+                    serde_json::from_slice(params.body.as_ref().unwrap().as_ref()).unwrap();
+                if let Some(id) = value.get("id") {
+                    let result = if value.get("method") == Some(&json!("initialize")) {
+                        json!({"protocolVersion":"2025-03-26","capabilities":{},"serverInfo":{"name":"fixed-pair-fixture","version":"1"}})
+                    } else {
+                        json!({"tools":[]})
+                    };
+                    return Ok(Self::response(
+                        200,
+                        json!({"jsonrpc":"2.0","id":id,"result":result}),
+                    ));
+                }
+                return Ok(Self::response(202, json!({})));
+            }
+            return Ok(Self::response(405, json!({})));
+        }
+        let mut response = Self::response(401, json!({}));
+        response.headers.push(HttpHeader{name:"www-authenticate".into(),value:format!("Bearer resource_metadata=\"https://mcp.mastermind-x.com/.well-known/oauth-protected-resource{}\"",Url::parse(&params.url).unwrap().path()),value_env_var:None});
+        Ok(response)
+    }
+}
