+async fn bound(http: Arc<FixtureHttp>, expired: bool) -> Arc<dyn HttpClient> {
+    let primary = tokens(false, now_ms().unwrap() + 600000);
+    let companion = tokens(
+        true,
+        if expired {
+            1
+        } else {
+            now_ms().unwrap() + 600000
+        },
+    );
+    save(&primary).await;
+    save(&companion).await;
+    bind_primary(
+        http,
+        &config(),
+        OAuthCredentialStore::new(
+            primary,
+            ResolvedOAuthCredentialStore::file(),
+            DefaultKeyringStore,
+            Some(config()),
+        ),
+        OAuthCredentialsStoreMode::File,
+        AuthKeyringBackendKind::Direct,
+        Arc::new(OnceLock::new()),
+        Arc::new(OnceLock::new()),
+        AuthStorageOriginator::current(),
+    )
+    .await
+    .unwrap()
+}
