+fn request() -> HttpRequestParams {
+    HttpRequestParams {
+        method: "POST".into(),
+        url: Workspace::PRIMARY_URL.into(),
+        headers: vec![HttpHeader {
+            name: "authorization".into(),
+            value: "Bearer executive-token".into(),
+            value_env_var: None,
+        }],
+        body: Some(br#"{"jsonrpc":"2.0","id":2,"method":"tools/list"}"#.to_vec().into()),
+        timeout_ms: Some(1000),
+        redirect_policy: HttpRedirectPolicy::Stop,
+        request_id: "original-operation".into(),
+        stream_response: false,
+    }
+}
