+    let mut url = Url::parse("https://login.mastermind-x.com/authorize").unwrap();
+    url.query_pairs_mut().extend_pairs([
+        ("client_id", CLIENT),
+        ("resource", Workspace::RESOURCE),
+        ("scope", Workspace::SCOPE),
+        ("response_type", "code"),
+        ("code_challenge_method", "S256"),
+        ("code_challenge", "challenge"),
+        ("state", "state"),
+    ]);
+    assert!(validate_authorization_url(url.as_str(), Workspace::RESOURCE, CLIENT, &scopes).is_ok());
+    url.query_pairs_mut()
+        .append_pair("resource", Workspace::RESOURCE);
+    assert!(
+        validate_authorization_url(url.as_str(), Workspace::RESOURCE, CLIENT, &scopes).is_err()
